import { useState, useEffect } from 'react'
import { Persons } from './components/Persons'
import { PersonForm } from './components/PersonForm'
import {Filter} from './components/Filter'
import personsService from './services/persons'
import { Notification } from './components/Notification'
const App = () => {
  const {getAll, create, deletePerson, update} = personsService

  const [allPersons, setAllPersons] = useState([])
  const [persons, setPersons] = useState([])
  const [successMsg, setSuccessMsg] = useState(null)
  const [errorMsg, setErrorMsg]=useState(null)
  useEffect(() => {
    getAll().then(initialPersons => {
      setPersons(initialPersons)
    })
  }, [allPersons])
  

  const handleSubmit = (event, newPerson) => {
    event.preventDefault()
    console.log('handleSubmit1', newPerson)
    
    
    persons.forEach(person => {
      if (person.name === newPerson.name && person.number !== newPerson.number) {
        if(window.confirm(`${person?.name} is already added to the phonebook, replace the old number with a new one?`)) {
          update(person.id, {newPerson}).then((response) => {
            const updatedPersons = persons.map((p)=> {
              if(p.id === person.id) {
                return {...person, number: newPerson.number}
              }
              return p
            })
            setPersons(updatedPersons)
          }).catch((e)=> {
            setErrorMsg(`Information of ${person.name} has already been removed`)
            setTimeout(() => {
          setErrorMsg(null)
        }, 5000)
          })
          return
        }
      }
      if (person.number === newPerson.number) {
        alert(`${newPerson.number} is already added to phonebook`)
        return
      }
    })
     create(newPerson).then(response => 
     { 
      setSuccessMsg(`Added ${newPerson.name}`)
      setTimeout(() => {
          setSuccessMsg(null)
        }, 5000)
      console.log(response.data)
      setAllPersons([...persons, response.data])
    })
  }

  const handleDelete = (personId) => {
      deletePerson(personId).then(() => {
        console.log('Deleted person with id:', personId)
        const newPersons = persons.filter((p)=> p.id !== personId)
        setPersons(newPersons)
      }).catch(error => {
          const personDeleted = persons.filter((p)=> p.id === personId)
          setErrorMsg(`Information of ${personDeleted.name} has already been removed`)
          setTimeout(() => {
          setErrorMsg(null)
        }, 5000)
          console.error('Error deleting person:', error)
        })
  }

  useEffect(() => {
    console.log('persons', persons)
  }, [persons])

 
  return (
    <div>
      <h2>Phonebook</h2>
      <Filter  persons={persons} />
      <h2>add a new</h2>
      <Notification message={successMsg} type={'success'}/>
      <Notification message={errorMsg} type={'error'}/>
      <PersonForm  handleSubmit={handleSubmit} />
      <h2>Numbers</h2>    
      <Persons persons={persons} handleDelete={handleDelete} /> 
    </div>
  )
}

export default App