import axios from 'axios';

const baseUrl = '/api/persons';

const getAll = () => {
  return axios.get(baseUrl).then(response => {
    console.log('getAll response', response.data);
    return response.data});
};

const create = newPerson => {
  console.log('create', newPerson)
  return axios.post(baseUrl, newPerson).then(() => {
    console.log('create response', newPerson)
    return {
      data: newPerson
    };
  }).catch(error => {
    console.error('Error creating person:', error);
    throw error;
  });
};

const update = (id, updatedPerson) => {
    return axios.put(`${baseUrl}/${id}`, updatedPerson).then(response => response.data);
};

const deletePerson = (id) => {
    return axios.delete(`${baseUrl}/${id}`).then(response => response.data);
};

const personsService = { getAll, create, update, deletePerson };

export default personsService;
