import { useState, useEffect } from "react";

export const Filter = ({ persons }) => {
    const [filteredPersons, setFilteredPersons] = useState([])
    const [filter, setFilter] = useState('')

    useEffect(()=> {
    
        const newFilteredPersons = !filter ? 
            [] : 
            persons.filter(person => person.name.toLowerCase().includes(filter.toLowerCase()))
        setFilteredPersons(newFilteredPersons)
    }, [filter])
    

    const handleFilterChange = (event) => {
    setFilter(event.target.value)
  }
    return ( 
    <>    <div>
        <label htmlFor="filter">filter shown with: </label>
        <input id="filter" value={filter} onChange={handleFilterChange} />
      
      </div>
      <div>
            {filteredPersons.length > 0 && filteredPersons.map((person) => <p key={person.name}>{person.name}: {person.number}</p>)}
    </div>
      </>
      )
}